import{_ as e,o as t,c as i,a5 as s}from"./chunks/framework.BZzouRtU.js";const u=JSON.parse('{"title":"ゲームの動きと構成から読む","description":"","frontmatter":{"title":"ゲームの動きと構成から読む","study":{"source":"新規執筆","section":"learning","format":"path","status":"published","domain":"game","collection":"foundations","order":5,"summary":"エンジン、時間、シーンと衝突から、入力、UI、プレハブ、ポーズ、イベント、セーブへ進む読み順。"}},"headers":[],"relativePath":"guide/game-development-basics.md","filePath":"guide/game-development-basics.md"}'),l={name:"guide/game-development-basics.md"};function o(r,a,n,d,h,m){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="ゲームの動きと構成から読む" tabindex="-1">ゲームの動きと構成から読む <a class="header-anchor" href="#ゲームの動きと構成から読む" aria-label="Permalink to &quot;ゲームの動きと構成から読む&quot;">​</a></h1><p>ゲームエンジンに任せる処理と、ゲームのルールを書く場所を確認します。プレイヤーを配置して動かし、壁に当たる場面を例に、用語がどの処理を指すかを追います。</p><p><a href="/study/learn/roadmap.html#game">ゲーム開発のテックツリー</a>では、シューティングの制作やECSなど、目標ごとに必要な前提と達成条件を確認できます。</p><h2 id="読む順番" tabindex="-1">読む順番 <a class="header-anchor" href="#読む順番" aria-label="Permalink to &quot;読む順番&quot;">​</a></h2><ol><li><a href="/study/game/basics/game-engine-basics.html">ゲームエンジンの役割</a>で、素材、制作ツール、実行する機能、ゲームのルールの関係をつかみます。</li><li><a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a>で、入力、状態の更新、描画を繰り返す流れを追います。</li><li><a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a>で、配置した物体に機能を組み合わせる方法を見ます。</li><li><a href="/study/game/basics/collisions-and-physics.html">衝突判定と物理</a>で、見た目の形、判定の形、接触後の動作を確かめます。</li></ol><h2 id="操作・表示・進行を組み立てる" tabindex="-1">操作・表示・進行を組み立てる <a class="header-anchor" href="#操作・表示・進行を組み立てる" aria-label="Permalink to &quot;操作・表示・進行を組み立てる&quot;">​</a></h2><ol><li><a href="/study/game/basics/input-actions-and-devices.html">入力アクションと機器</a>で、キーやパッドの操作をゲームの意味へ対応させます。</li><li><a href="/study/game/basics/ui-layout-and-interaction.html">UIの配置と操作</a>で、HPやメニューを画面に置き、操作を受け付ける方法を見ます。</li><li><a href="/study/game/basics/prefabs-and-object-lifetimes.html">プレハブとオブジェクトの寿命</a>で、同じ設定から物体を作り、有効化・無効化・破棄を扱います。</li><li><a href="/study/game/basics/game-states-and-pause.html">ゲームの状態とポーズ</a>で、今の場面に応じて入力と更新を切り替えます。</li><li><a href="/study/game/basics/game-events-and-notifications.html">ゲーム内イベントと通知</a>で、HPなどの変化を必要な表示へ伝えます。</li><li><a href="/study/game/basics/save-data-and-serialization.html">セーブデータとシリアライズ</a>で、次の起動へ引き継ぐ情報を保存し、読み戻す流れを見ます。</li></ol><h2 id="確かめること" tabindex="-1">確かめること <a class="header-anchor" href="#確かめること" aria-label="Permalink to &quot;確かめること&quot;">​</a></h2><ul><li>素材のファイルと、実行中のオブジェクトや値の関係を説明できる。</li><li>描画フレームと、状態を進める更新の回数を分けて数えられる。</li><li>描画、衝突判定、物理、ゲームのルールが、それぞれ何を担当するか説明できる。</li></ul><h2 id="小さなゲームにまとめる" tabindex="-1">小さなゲームにまとめる <a class="header-anchor" href="#小さなゲームにまとめる" aria-label="Permalink to &quot;小さなゲームにまとめる&quot;">​</a></h2><p><a href="/study/game/shooter-design.html">小さなシューティングの設計</a>では、入力、移動、弾、敵、HPをつなげて考えます。設計を読んでから、<a href="/study/game/shooter-cpp.html">C++版</a>または<a href="/study/game/shooter-unity.html">UnityのC#版</a>へ進めます。</p><p>画像が作られる側は<a href="/study/guide/graphics-basics.html">3DCGの基礎</a>、コードの読み方や実行方法は<a href="/study/guide/software-development-basics.html">プログラムを書く・動かす基礎</a>で確認できます。</p>',12)])])}const p=e(l,[["render",o]]);export{u as __pageData,p as default};
